def smoke_bytes(seed: str, nbytes: int) -> bytes:
    """契约 §2：``SHA256(seed + ":" + str(i))`` 串联后截断（每轮 32 字节）。"""
    out = b""
    i = 0
    while len(out) < nbytes:
        out += hashlib.sha256(f"{seed}:{i}".encode("utf-8")).digest()
        i += 1
    return out[:nbytes]


